def _pakad(kisse, kya):
    return ('उसने उसे %s से पकड़ना चाहा, पर न पकड़ सका। अगर वह उसे %s से पकड़ लेता, तो अन्न को %s भर से पेट भर जाता।'
            % (kisse, kisse, kya))


